1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11	)
12	
13	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
14	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
15	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
16	type Registry struct {
17		dir    string
18		store  *store
19		state  *snapshot
20		mu     sync.Mutex
21		closed bool
22	}
23	
24	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
25	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
26	// 已有的数据不会被覆盖。
27	func Create(dir string) (*Registry, error) {
28		if strings.TrimSpace(dir) == "" {
29			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
30		}
31		if err := os.MkdirAll(dir, dirMode); err != nil {
32			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
33		}
34		if _, err := os.Stat(dataFile(dir)); err == nil {
35			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
36		} else if !errors.Is(err, os.ErrNotExist) {
37			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
38		}
39		lock, err := acquireLock(dir)
40		if err != nil {
41			return nil, err
42		}
43		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
44		if _, err := os.Stat(dataFile(dir)); err == nil {
45			_ = releaseLock(lock)
46			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
47		}
48		st := &store{dir: dir, lock: lock}
49		s := newSnapshot()
50		if err := st.save(s); err != nil {
51			_ = releaseLock(lock)
52			return nil, err
53		}
54		return &Registry{dir: dir, store: st, state: s}, nil
55	}
56	
57	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
58	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
59	// 错误，不会被静默当成空登记册。
60	func Open(dir string) (*Registry, error) {
61		if strings.TrimSpace(dir) == "" {
62			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
63		}
64		if info, err := os.Stat(dir); err != nil {
65			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
66		} else if !info.IsDir() {
67			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
68		}
69		lock, err := acquireLock(dir)
70		if err != nil {
71			return nil, err
72		}
73		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
74		// 绝不把无数据目录静默当成空登记册。
75		if _, err := os.Stat(dataFile(dir)); err != nil {
76			_ = releaseLock(lock)
77			if errors.Is(err, os.ErrNotExist) {
78				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
79			}
80			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
81		}
82		s, err := load(dir)
83		if err != nil {
84			_ = releaseLock(lock)
85			return nil, err
86		}
87		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s}, nil
88	}
89	
90	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
91	func (r *Registry) Close() error {
92		r.mu.Lock()
93		defer r.mu.Unlock()
94		if r.closed {
95			return nil
96		}
97		r.closed = true
98		return releaseLock(r.store.lock)
99	}
100	
101	func releaseLock(f *os.File) error {
102		err := f.Close() // Close 同时释放 flock
103		if err != nil {
104			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
105		}
106		return nil
107	}
108	
109	func (r *Registry) checkOpen() error {
110		if r.closed {
111			return fmt.Errorf("registry: 登记册已关闭")
112		}
113		return nil
114	}
115	
116	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
117	// 避免内存状态与已持久化状态不一致。
118	func (r *Registry) commit() error {
119		if err := r.store.save(r.state); err != nil {
120			if s, lerr := load(r.dir); lerr == nil {
121				r.state = s
122			}
123			return err
124		}
125		return nil
126	}
127	
128	// ---- 账户 ----
129	
130	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
131	func (r *Registry) RegisterAccount(id, metadata string) error {
132		r.mu.Lock()
133		defer r.mu.Unlock()
134		if err := r.checkOpen(); err != nil {
135			return err
136		}
137		if strings.TrimSpace(id) == "" {
138			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
139		}
140		if _, ok := r.state.Accounts[id]; ok {
141			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
142		}
143		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
144		return r.commit()
145	}
146	
147	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
148	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
149	func (r *Registry) DeactivateAccount(id string) error {
150		r.mu.Lock()
151		defer r.mu.Unlock()
152		if err := r.checkOpen(); err != nil {
153			return err
154		}
155		a, ok := r.state.Accounts[id]
156		if !ok {
157			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
158		}
159		if !a.Active {
160			return nil // 停用是幂等的终态
161		}
162		a.Active = false
163		r.state.Accounts[id] = a
164		return r.commit()
165	}
166	
167	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
168	func (r *Registry) GetAccount(id string) (Account, error) {
169		r.mu.Lock()
170		defer r.mu.Unlock()
171		if err := r.checkOpen(); err != nil {
172			return Account{}, err
173		}
174		a, ok := r.state.Accounts[id]
175		if !ok {
176			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
177		}
178		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
179	}
180	
181	// ---- 系列 ----
182	
183	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
184	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
185	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
186		r.mu.Lock()
187		defer r.mu.Unlock()
188		if err := r.checkOpen(); err != nil {
189			return err
190		}
191		if strings.TrimSpace(id) == "" {
192			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
193		}
194		creator, ok := r.state.Accounts[creatorID]
195		if !ok {
196			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
197		}
198		if !creator.Active {
199			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
200		}
201		if _, ok := r.state.Series[id]; ok {
202			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
203		}
204		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
205		return r.commit()
206	}
207	
208	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
209	// 已发行藏品仍可转让，且封存不能撤销。
210	func (r *Registry) SealSeries(seriesID, operator string) error {
211		r.mu.Lock()
212		defer r.mu.Unlock()
213		if err := r.checkOpen(); err != nil {
214			return err
215		}
216		s, ok := r.state.Series[seriesID]
217		if !ok {
218			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
219		}
220		if s.CreatorID != operator {
221			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
222		}
223		if s.Sealed {
224			return nil // 封存不可撤销，重复封存视为已处于封存态
225		}
226		s.Sealed = true
227		r.state.Series[seriesID] = s
228		return r.commit()
229	}
230	
231	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
232	func (r *Registry) GetSeries(id string) (Series, error) {
233		r.mu.Lock()
234		defer r.mu.Unlock()
235		if err := r.checkOpen(); err != nil {
236			return Series{}, err
237		}
238		s, ok := r.state.Series[id]
239		if !ok {
240			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
241		}
242		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
243	}
244	
245	// ---- 发行 ----
246	
247	func (req IssueRequest) validatePresent() error {
248		missing := []string{}
249		if strings.TrimSpace(req.Operator) == "" {
250			missing = append(missing, "operator")
251		}
252		if strings.TrimSpace(req.Reason) == "" {
253			missing = append(missing, "reason")
254		}
255		if strings.TrimSpace(req.RequestID) == "" {
256			missing = append(missing, "request_id")
257		}
258		if strings.TrimSpace(req.ItemID) == "" {
259			missing = append(missing, "item_id")
260		}
261		if strings.TrimSpace(req.SeriesID) == "" {
262			missing = append(missing, "series_id")
263		}
264		if strings.TrimSpace(req.BatchNo) == "" {
265			missing = append(missing, "batch_no")
266		}
267		if strings.TrimSpace(req.HolderID) == "" {
268			missing = append(missing, "holder_id")
269		}
270		if len(missing) > 0 {
271			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
272		}
273		return nil
274	}
275	
276	func issueParamsSig(req IssueRequest) string {
277		b, _ := json.Marshal(struct {
278			Kind     string `json:"kind"`
279			ItemID   string `json:"item_id"`
280			SeriesID string `json:"series_id"`
281			BatchNo  string `json:"batch_no"`
282			Metadata string `json:"metadata"`
283			HolderID string `json:"holder_id"`
284			Reason   string `json:"reason"`
285		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
286		return string(b)
287	}
288	
289	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
290	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
291	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
292	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
293	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
294		if err := req.validatePresent(); err != nil {
295			return IssueResult{}, err
296		}
297		r.mu.Lock()
298		defer r.mu.Unlock()
299		if err := r.checkOpen(); err != nil {
300			return IssueResult{}, err
301		}
302	
303		key := requestKey(req.Operator, req.RequestID)
304		sig := issueParamsSig(req)
305		if prev, ok := r.state.Requests[key]; ok {
306			return r.replayIssue(prev, sig)
307		}
308	
309		bizErr := r.checkIssue(req)
310		if bizErr != nil {
311			if !isValidationErr(bizErr) {
312				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
313				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
314				r.state.Requests[key] = request{
315					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
316					Params: sig, Rejected: true, Reason: errCode(bizErr),
317					ItemID: req.ItemID,
318				}
319				_ = r.commit()
320			}
321			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
322			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
323		}
324	
325		seq := r.state.NextSeq + 1
326		r.state.NextSeq = seq
327		r.state.Items[req.ItemID] = item{
328			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
329			Metadata: req.Metadata, IssuedTxID: seq,
330		}
331		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
332		r.state.History = append(r.state.History, historyEntry{
333			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
334			Reason: req.Reason, RequestID: req.RequestID,
335			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
336		})
337		r.state.Requests[key] = request{
338			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
339			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
340		}
341		if err := r.commit(); err != nil {
342			return IssueResult{}, err
343		}
344		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
345	}
346	
347	func (r *Registry) checkIssue(req IssueRequest) error {
348		op, ok := r.state.Accounts[req.Operator]
349		if !ok {
350			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
351		}
352		if !op.Active {
353			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
354		}
355		s, ok := r.state.Series[req.SeriesID]
356		if !ok {
357			return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
358		}
359		if s.Sealed {
360			return fmt.Errorf("%w: 系列 %s", ErrSeriesSealed, req.SeriesID)
361		}
362		if s.CreatorID != req.Operator {
363			return fmt.Errorf("%w: 只有系列创建账户 %s 可以发行", ErrForbidden, s.CreatorID)
364		}
365		if _, ok := r.state.Items[req.ItemID]; ok {
366			return fmt.Errorf("%w: 藏品编号 %s 已被使用", ErrAlreadyExists, req.ItemID)
367		}
368		h, ok := r.state.Accounts[req.HolderID]
369		if !ok {
370			return fmt.Errorf("%w: 初始持有人账户 %s", ErrNotFound, req.HolderID)
371		}
372		if !h.Active {
373			return fmt.Errorf("%w: 初始持有人账户 %s", ErrAccountInactive, req.HolderID)
374		}
375		return nil
376	}
377	
378	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
379		if prev.Kind != "issue" || prev.Params != sig {
380			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
381				ErrRequestConflict, prev.Operator, prev.RequestID)
382		}
383		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
384			TxSeq: prev.TxSeq, Replayed: true}
385		if prev.Rejected {
386			res.Err = codeErr(prev.Reason)
387			return res, res.Err
388		}
389		return res, nil
390	}
391	
392	// ---- 转让 ----
393	
394	func (req TransferRequest) validatePresent() error {
395		missing := []string{}
396		if strings.TrimSpace(req.Operator) == "" {
397			missing = append(missing, "operator")
398		}
399		if strings.TrimSpace(req.Reason) == "" {
400			missing = append(missing, "reason")
401		}
402		if strings.TrimSpace(req.RequestID) == "" {
403			missing = append(missing, "request_id")
404		}
405		if strings.TrimSpace(req.ItemID) == "" {
406			missing = append(missing, "item_id")
407		}
408		if strings.TrimSpace(req.ExpectedOwner) == "" {
409			missing = append(missing, "expected_owner")
410		}
411		if strings.TrimSpace(req.ToID) == "" {
412			missing = append(missing, "to_id")
413		}
414		if req.ExpectedVer <= 0 {
415			missing = append(missing, "expected_version")
416		}
417		if len(missing) > 0 {
418			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
419		}
420		return nil
421	}
422	
423	func transferParamsSig(req TransferRequest) string {
424		b, _ := json.Marshal(struct {
425			Kind          string `json:"kind"`
426			ItemID        string `json:"item_id"`
427			ExpectedOwner string `json:"expected_owner"`
428			ExpectedVer   int64  `json:"expected_version"`
429			ToID          string `json:"to_id"`
430			Reason        string `json:"reason"`
431		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Reason})
432		return string(b)
433	}
434	
435	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
436	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
437	// 不符时返回业务拒绝且不改变任何状态。同一 (操作者, 请求号) 的相同
438	// 请求重复提交（即使藏品后来已易手）返回首次结果。
439	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
440		if err := req.validatePresent(); err != nil {
441			return TransferResult{}, err
442		}
443		r.mu.Lock()
444		defer r.mu.Unlock()
445		if err := r.checkOpen(); err != nil {
446			return TransferResult{}, err
447		}
448	
449		key := requestKey(req.Operator, req.RequestID)
450		sig := transferParamsSig(req)
451		if prev, ok := r.state.Requests[key]; ok {
452			return r.replayTransfer(prev, sig)
453		}
454	
455		bizErr := r.checkTransfer(req)
456		if bizErr != nil {
457			if !isValidationErr(bizErr) {
458				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
459				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
460				r.state.Requests[key] = request{
461					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
462					Params: sig, Rejected: true, Reason: errCode(bizErr),
463					ItemID: req.ItemID,
464				}
465				_ = r.commit()
466			}
467			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
468			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
469		}
470	
471		h := r.state.Holdings[req.ItemID]
472		seq := r.state.NextSeq + 1
473		r.state.NextSeq = seq
474		from := h.OwnerID
475		fromVer := h.Version
476		h.OwnerID = req.ToID
477		h.Version = fromVer + 1
478		r.state.Holdings[req.ItemID] = h
479		r.state.History = append(r.state.History, historyEntry{
480			Seq: seq, Kind: "transfer", ItemID: req.ItemID, Operator: req.Operator,
481			Reason: req.Reason, RequestID: req.RequestID,
482			FromID: from, ToID: req.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
483		})
484		r.state.Requests[key] = request{
485			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
486			Params: sig, ItemID: req.ItemID, FromID: from, ToID: req.ToID,
487			Version: fromVer + 1, TxSeq: seq,
488		}
489		if err := r.commit(); err != nil {
490			return TransferResult{}, err
491		}
492		return TransferResult{ItemID: req.ItemID, FromID: from, ToID: req.ToID,
493			Version: fromVer + 1, TxSeq: seq}, nil
494	}
495	
496	func (r *Registry) checkTransfer(req TransferRequest) error {
497		h, ok := r.state.Holdings[req.ItemID]
498		if !ok {
499			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
500				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
501			}
502			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
503		}
504		op, ok := r.state.Accounts[req.Operator]
505		if !ok {
506			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
507		}
508		if !op.Active {
509			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
510		}
511		to, ok := r.state.Accounts[req.ToID]
512		if !ok {
513			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
514		}
515		if !to.Active {
516			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
517		}
518		if req.ToID == h.OwnerID {
519			return fmt.Errorf("%w: 接收人 %s 已是当前持有人", ErrSameAccount, req.ToID)
520		}
521		// 期望持有人或期望版本不符，包括发起人并非当前持有人的情况。
522		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
523			req.Operator != h.OwnerID {
524			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d", ErrConflict,
525				req.ItemID, h.OwnerID, h.Version)
526		}
527		return nil
528	}
529	
530	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
531		if prev.Kind != "transfer" || prev.Params != sig {
532			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
533				ErrRequestConflict, prev.Operator, prev.RequestID)
534		}
535		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
536			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
537		if prev.Rejected {
538			res.Err = codeErr(prev.Reason)
539			return res, res.Err
540		}
541		return res, nil
542	}
543	
544	// ---- 查询 ----
545	
546	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
547	func (r *Registry) GetItem(id string) (Item, error) {
548		r.mu.Lock()
549		defer r.mu.Unlock()
550		if err := r.checkOpen(); err != nil {
551			return Item{}, err
552		}
553		it, ok := r.state.Items[id]
554		if !ok {
555			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
556		}
557		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
558			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
559	}
560	
561	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
562	func (r *Registry) GetHolding(itemID string) (Holding, error) {
563		r.mu.Lock()
564		defer r.mu.Unlock()
565		if err := r.checkOpen(); err != nil {
566			return Holding{}, err
567		}
568		h, ok := r.state.Holdings[itemID]
569		if !ok {
570			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
571		}
572		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
573	}
574	
575	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
576	// ErrNotFound 的错误；停用账户仍可正常查询。
577	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
578		r.mu.Lock()
579		defer r.mu.Unlock()
580		if err := r.checkOpen(); err != nil {
581			return nil, err
582		}
583		if _, ok := r.state.Accounts[accountID]; !ok {
584			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
585		}
586		out := make([]Holding, 0)
587		for _, h := range r.state.Holdings {
588			if h.OwnerID == accountID {
589				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
590			}
591		}
592		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
593		return out, nil
594	}
595	
596	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
597	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
598	// 返回包裹 ErrNotFound 的错误。
599	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
600		r.mu.Lock()
601		defer r.mu.Unlock()
602		if err := r.checkOpen(); err != nil {
603			return nil, err
604		}
605		if _, ok := r.state.Items[itemID]; !ok {
606			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
607		}
608		out := make([]HistoryEntry, 0)
609		for _, e := range r.state.History {
610			if e.ItemID != itemID {
611				continue
612			}
613			out = append(out, HistoryEntry{
614				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
615				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
616				FromVersion: e.FromVersion, ToVersion: e.ToVersion,
617			})
618		}
619		return out, nil
620	}
621	
622	// ---- 幂等辅助 ----
623	
624	func requestKey(operator, requestID string) string {
625		return operator + "\x00" + requestID
626	}
627	
628	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
629	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
630	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
631	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
632	// 并回放。
633	func isValidationErr(err error) bool {
634		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
635	}
636	
637	var errCodes = map[error]string{
638		ErrNotFound:        "not_found",
639		ErrAlreadyExists:   "already_exists",
640		ErrAccountInactive: "account_inactive",
641		ErrSeriesSealed:    "series_sealed",
642		ErrConflict:        "conflict",
643		ErrSameAccount:     "same_account",
644		ErrForbidden:       "forbidden",
645	}
646	
647	var codeErrs = map[string]error{
648		"not_found":        ErrNotFound,
649		"already_exists":   ErrAlreadyExists,
650		"account_inactive": ErrAccountInactive,
651		"series_sealed":    ErrSeriesSealed,
652		"conflict":         ErrConflict,
653		"same_account":     ErrSameAccount,
654		"forbidden":        ErrForbidden,
655	}
656	
657	func errCode(err error) string {
658		for sentinel, code := range errCodes {
659			if errors.Is(err, sentinel) {
660				return code
661			}
662		}
663		return "rejected"
664	}
665	
666	func codeErr(code string) error {
667		if e, ok := codeErrs[code]; ok {
668			return e
669		}
670		return errors.New("registry: 请求曾被拒绝")
671	}
672

