281	
282	func TestTransferValidation(t *testing.T) {
283		r := mustCreate(t, tempDir(t))
284		setupWorld(t, r)
285		r.RegisterAccount("carol", "")
286		r.Issue(issueReq("i1", "alice"))
287	
288		// 不存在的藏品
289		if _, err := r.Transfer(xferReq("alice", "nope", "bob", 1, "x1")); !errors.Is(err, ErrNotFound) {
290			t.Fatalf("got %v", err)
291		}
292		// 发起人不是当前持有人
293		if _, err := r.Transfer(xferReq("bob", "i1", "carol", 1, "x2")); !errors.Is(err, ErrConflict) {
294			t.Fatalf("non-holder transfer must conflict, got %v", err)
295		}
296		// 版本不符
297		if _, err := r.Transfer(xferReq("alice", "i1", "carol", 9, "x3")); !errors.Is(err, ErrConflict) {
298			t.Fatalf("wrong version must conflict, got %v", err)
299		}
300		// 期望持有人填错
301		bad := xferReq("alice", "i1", "carol", 1, "x4")
302		bad.ExpectedOwner = "bob"
303		if _, err := r.Transfer(bad); !errors.Is(err, ErrConflict) {
304			t.Fatalf("wrong expected owner must conflict, got %v", err)
