	a, err := r.GetAuth("a1")
	if err != nil {
		t.Fatal(err)
	}
	if a.ItemID != "i1" || a.Authorizer != "alice" || a.Trustee != "bob" ||
		a.Receiver != "carol" || a.HolderID != "alice" || a.Version != 1 ||
		a.Revoked || a.Used || a.UsedTxID != 0 {
		t.Fatalf("auth wrong: %+v", a)
	}
